solutionText:
\(
\begin{cases} 
x^2 - 5ax + 4a \geq 0, \\ 
\left[ \begin{array}{l}
x = -a, \\
a = 0, \\
x = \frac{4 - a}{3}.
\end{array} \right.
\end{cases}
\)

